// src/rules/systems/aiPolicySystem.js
// Neural-network policy override for high-intelligence monsters (intel ≥ 7).
//
// Runs AFTER aiChaseSystem in the 'ai' phase.
//
// Contract:
//   • If the entity already has CastSpellIntent (set by a whileLOS hook), skip it —
//     the hook made a contextual decision and we don't want to second-guess it here.
//   • Otherwise: extract features → forward pass → argmax → applyAction.
//     applyAction can replace MoveIntent with a better direction, add CastSpellIntent,
//     or remove MoveIntent (wait/hold).
//   • Falls back silently if no trained weights exist for this tier (TRAINED_WEIGHTS empty).

import { Faction }       from '../components/Faction.js';
import { Brain }         from '../components/Brain.js';
import { AggroState, AGGRO_LEVELS } from '../components/AggroState.js';
import { NamedIdentity } from '../components/NamedIdentity.js';
import { CastSpellIntent } from '../components/Intents/CastSpellIntent.js';
import { forEachInRadius } from '../utils/spatialIndex.js';
import { playerEntity }    from '../utils/queries.js';
import { canActThisTurn }  from '../utils/speedGate.js';
import { hasLOS }          from '../../shared/math/gridLOS.js';
import { buildBlocksVisionMap, blockedCallback } from '../utils/vision.js';
import { chebyshevScalar } from '../utils/distance.js';
import { getMonster }      from '../data/monsters.js';
import { extractFeatures } from '../ai/policyFeatures.js';
import { forward, argmax, deserializeNet } from '../ai/tinyMLP.js';
import { applyAction }     from '../ai/policyAction.js';
import { getWeightsForIntelligence } from '../data/aiWeights.js';

const POLICY_INTEL_THRESHOLD = 7;
const ACTIVE_RADIUS          = 32;

// Cache deserialised networks keyed by tier string (lives for the page lifetime).
/** @type {Map<string, ReturnType<import('../ai/tinyMLP.js').createMLP>>} */
const NET_CACHE = new Map();

/**
 * @param {number} intel
 * @returns {ReturnType<import('../ai/tinyMLP.js').createMLP> | null}
 */
function getNet(intel) {
  const tier = intel >= 9 ? 'caster' : 'tactical';
  if (NET_CACHE.has(tier)) return NET_CACHE.get(tier);

  const spec = getWeightsForIntelligence(intel);
  if (!spec) return null; // untrained — policy inactive for this tier

  const net = deserializeNet(spec);
  NET_CACHE.set(tier, net);
  return net;
}

/** @param {any} world */
export function aiPolicySystem(world) {
  const _player = playerEntity(world);
  if (!_player) return;

  const playerId  = _player.id;
  const playerPos = _player.pos;

  // LOS blocking map — built once per tick, shared.
  let _isBlocked = null;
  function ensureBlocked() {
    if (!_isBlocked) _isBlocked = blockedCallback(buildBlocksVisionMap(world));
    return _isBlocked;
  }

  forEachInRadius(world, playerPos.x, playerPos.y, ACTIVE_RADIUS, (id, pos) => {
    // Only enemy entities
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== 'enemy') return;

    // Intelligence gate
    const brain = world.get(id, Brain);
    const intel = Number(brain?.intelligence ?? 10);
    if (intel < POLICY_INTEL_THRESHOLD) return;

    // Only act when hunting and it's this monster's turn
    const aggro = world.get(id, AggroState);
    if (!aggro || aggro.alertLevel !== AGGRO_LEVELS.hunting) return;
    if (!canActThisTurn(world, id)) return;

    // If a whileLOS hook already cast a spell this tick, don't interfere
    if (world.has(id, CastSpellIntent)) return;

    // Network must be trained for this tier
    const net = getNet(intel);
    if (!net) return;

    // LOS check (monsters without LOS are handled by aiChaseSystem's search)
    const dist = chebyshevScalar(pos.x | 0, pos.y | 0, playerPos.x | 0, playerPos.y | 0);
    if (dist > (brain?.visionRange ?? 8)) return;
    const canSee = hasLOS(
      pos.x | 0, pos.y | 0,
      playerPos.x | 0, playerPos.y | 0,
      ensureBlocked(),
    );
    if (!canSee) return;

    // Extract features and run policy
    const features = extractFeatures(world, id, pos, playerId, playerPos);
    const probs    = forward(net, features);
    const action   = argmax(probs);

    const learnedSpells = Array.isArray(brain?.learnedSpellIds) ? brain.learnedSpellIds : [];
    applyAction(world, id, playerId, action, learnedSpells);
  });
}
// src/rules/ai/policyAction.js
// Map the neural network's output index → a concrete game intent for a monster.
//
// Action space (14 outputs):
//   0-7   Movement directions (N, NE, E, SE, S, SW, W, NW)
//   8     Wait / hold position
//   9-12  Cast learnedSpells[0-3]
//   13    Use ranged weapon (keeps existing RangedAttackIntent or adds one)
//
// Integration contract:
//   • Called AFTER aiChaseSystem has run.
//   • If entity already has CastSpellIntent the hook already decided — skip.
//   • Movement direction: replace existing MoveIntent with policy-chosen direction.
//   • Spell cast:  remove MoveIntent + add CastSpellIntent + mark cooldown.
//   • Wait (8):    remove MoveIntent (monster holds its position this turn).
//   • Ranged (13): leave existing RangedAttackIntent if present; otherwise pass.

import { MoveIntent }        from '../components/Intents/MoveIntent.js';
import { CastSpellIntent }   from '../components/Intents/CastSpellIntent.js';
import { RangedAttackIntent } from '../components/Intents/RangedAttackIntent.js';
import { Mana }              from '../components/Mana.js';
import { isAiOnCooldown, startAiCooldown } from '../utils/aiCooldowns.js';

// Must match the key used by castSpellOnLOS so cooldowns are shared.
const SPELL_CAST_COOLDOWN_KEY = Symbol.for("jshack:ai:castSpellOnLOS:cooldown");
const POLICY_SPELL_COOLDOWN   = 8; // turns between policy-initiated casts

function spellSlot(actorId, spellId) {
  return `${actorId | 0}:${String(spellId || '')}`;
}

// Ordered direction table: index 0 = N, clockwise.
export const MOVE_DIRS = [
  { dx:  0, dy: -1 }, // 0 N
  { dx:  1, dy: -1 }, // 1 NE
  { dx:  1, dy:  0 }, // 2 E
  { dx:  1, dy:  1 }, // 3 SE
  { dx:  0, dy:  1 }, // 4 S
  { dx: -1, dy:  1 }, // 5 SW
  { dx: -1, dy:  0 }, // 6 W
  { dx: -1, dy: -1 }, // 7 NW
];

export const ACTION_WAIT      = 8;
export const ACTION_SPELL_0   = 9;
export const ACTION_SPELL_MAX = 12; // inclusive
export const ACTION_RANGED    = 13;
export const ACTION_COUNT     = 14;

/**
 * Apply the network's chosen action to the entity.
 * Returns the action index actually applied (may fall back if spell unavailable).
 *
 * @param {any}    world
 * @param {number} actorId
 * @param {number} targetId
 * @param {number} actionIdx   0-13 from argmax(forward())
 * @param {string[]} learnedSpells  brain.learnedSpellIds
 */
export function applyAction(world, actorId, targetId, actionIdx, learnedSpells) {
  // ── Spell cast (9-12) ───────────────────────────────────────────────────────
  if (actionIdx >= ACTION_SPELL_0 && actionIdx <= ACTION_SPELL_MAX) {
    const spellIdx = actionIdx - ACTION_SPELL_0;
    const spellId  = learnedSpells[spellIdx];

    if (spellId) {
      const slot = spellSlot(actorId, spellId);
      const onCooldown = isAiOnCooldown(world, SPELL_CAST_COOLDOWN_KEY, slot);
      const mana = world.get(actorId, Mana);
      const hasMana = !mana || mana.mana >= 8;

      if (!onCooldown && hasMana) {
        // Remove any movement intent before casting
        if (world.has(actorId, MoveIntent)) {
          try { world.remove(actorId, MoveIntent); } catch {}
        }
        try {
          world.add(actorId, CastSpellIntent, { spellId, targetId, x: null, y: null });
          startAiCooldown(world, SPELL_CAST_COOLDOWN_KEY, slot, POLICY_SPELL_COOLDOWN);
          return actionIdx;
        } catch {
          // CastSpellIntent already present (unlikely but guard it)
        }
      }
    }

    // Spell unavailable — fall back to move toward target (actionIdx 4 = S approximation;
    // actual direction is computed in the fallback block below by the caller, but we can
    // return ACTION_WAIT so existing MoveIntent from aiChaseSystem is preserved).
    return ACTION_WAIT; // don't override movement, let chase-system move stand
  }

  // ── Wait / hold (8) ─────────────────────────────────────────────────────────
  if (actionIdx === ACTION_WAIT) {
    if (world.has(actorId, MoveIntent)) {
      try { world.remove(actorId, MoveIntent); } catch {}
    }
    return ACTION_WAIT;
  }

  // ── Ranged (13) ─────────────────────────────────────────────────────────────
  if (actionIdx === ACTION_RANGED) {
    // If aiChaseSystem already set a RangedAttackIntent, leave it.
    // Otherwise policy can't add ranged without weapon validation, so just wait.
    if (!world.has(actorId, RangedAttackIntent)) {
      // Nothing to do; let the turn pass
    }
    return ACTION_RANGED;
  }

  // ── Movement (0-7) ──────────────────────────────────────────────────────────
  if (actionIdx >= 0 && actionIdx <= 7) {
    const dir = MOVE_DIRS[actionIdx];
    if (world.has(actorId, MoveIntent)) {
      const existing = world.get(actorId, MoveIntent);
      if (existing && existing.dx === dir.dx && existing.dy === dir.dy) {
        return actionIdx; // same direction, no-op
      }
      try { world.remove(actorId, MoveIntent); } catch {}
    }
    try {
      world.add(actorId, MoveIntent, { dx: dir.dx, dy: dir.dy });
    } catch {}
    return actionIdx;
  }

  return actionIdx;
}

/**
 * Argmax helper (re-exported for callers that want it alongside this module).
 * @param {Float64Array} probs
 * @returns {number}
 */
export function argmax(probs) {
  let best = 0;
  for (let i = 1; i < probs.length; i++) if (probs[i] > probs[best]) best = i;
  return best;
}
