import "file:///home/pjensen/Repos/JSHack/tests/helpers/installContentMonsters.mjs";
import { World } from "file:///home/pjensen/Repos/JSHack/src/lib/ecs-js/index.js";
import { createPlayer } from "file:///home/pjensen/Repos/JSHack/src/rules/archetypes/Player.js";
import { spawnMonsterEntity } from "file:///home/pjensen/Repos/JSHack/src/rules/utils/spawnMonsterEntity.js";
import { getMonster } from "file:///home/pjensen/Repos/JSHack/src/rules/data/monsters.js";
import { toMonsterSpawnParams } from "file:///home/pjensen/Repos/JSHack/src/rules/utils/monsterSpawnParams.js";
import { Position } from "file:///home/pjensen/Repos/JSHack/src/rules/components/Position.js";
import { Brain } from "file:///home/pjensen/Repos/JSHack/src/rules/components/Brain.js";
import { ActiveEffects } from "file:///home/pjensen/Repos/JSHack/src/rules/components/ActiveEffects.js";
import { AggroState, AGGRO_LEVELS } from "file:///home/pjensen/Repos/JSHack/src/rules/components/AggroState.js";
import { MoveIntent } from "file:///home/pjensen/Repos/JSHack/src/rules/components/Intents/MoveIntent.js";
import { RangedAttackIntent } from "file:///home/pjensen/Repos/JSHack/src/rules/components/Intents/RangedAttackIntent.js";
import { aiChaseSystem } from "file:///home/pjensen/Repos/JSHack/src/rules/systems/aiChaseSystem.js";
import { aiPolicySystem } from "file:///home/pjensen/Repos/JSHack/src/rules/systems/aiPolicySystem.js";
import { rebuildSpatialIndex } from "file:///home/pjensen/Repos/JSHack/src/rules/utils/spatialIndex.js";
import { clearAll, loadChunk } from "file:///home/pjensen/Repos/JSHack/src/rules/environment/dungeon/tileMap.js";
import { CHUNK_SIZE, TILE_FLOOR, TILE_WALL } from "file:///home/pjensen/Repos/JSHack/src/rules/environment/dungeon/constants.js";

const TURNS = 8;

function setup({ corridor = false, archer = false, stunned = false } = {}) {
  clearAll();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE).fill(TILE_FLOOR);
  if (corridor) {
    for (let x = 0; x < CHUNK_SIZE; x++) {
      tiles[4 * CHUNK_SIZE + x] = TILE_WALL;
      tiles[6 * CHUNK_SIZE + x] = TILE_WALL;
    }
  }
  loadChunk(0, 0, tiles);
  const world = new World({ seed: 186 });
  const player = createPlayer(world, { x: 8, y: 5, maxHp: 30, hp: 30 });
  const ids = [];
  const identity = archer ? "goblin_archer" : "goblin";
  const base = toMonsterSpawnParams(getMonster(identity), 1);
  for (const [x, y] of (corridor ? [[16, 5], [15, 5], [14, 5]] : [[14, 4], [14, 5], [14, 6]])) {
    const id = spawnMonsterEntity(world, { ...base, x, y, maxHp: 20, hp: 20 });
    const brain = world.get(id, Brain);
    brain.intelligence = 8;
    world.add(id, AggroState, {
      alertLevel: AGGRO_LEVELS.hunting,
      lastKnownX: 8, lastKnownY: 5, searchTurnsLeft: 10, retreating: false,
    });
    if (stunned && ids.length === 0) {
      world.get(id, ActiveEffects).effects.push({ key: "stun", turnsLeft: 3, potency: 1, stacks: 1 });
    }
    ids.push(id);
  }
  rebuildSpatialIndex(world);
  return { world, player, ids };
}

function snapshot(world, player, ids) {
  const pp = world.get(player, Position);
  return {
    player: [pp.x, pp.y],
    monsters: ids.map((id) => {
      const p = world.get(id, Position);
      const move = world.get(id, MoveIntent);
      return {
        pos: [p.x, p.y],
        move: move ? [move.dx, move.dy] : null,
        ranged: world.has(id, RangedAttackIntent),
      };
    }),
  };
}

function run(name, options = {}) {
  const { world, player, ids } = setup(options);
  const trace = [];
  for (let turn = 0; turn < TURNS; turn++) {
    const pp = world.get(player, Position);
    if (options.playerStrategy === "retreat") pp.x -= 1;
    aiChaseSystem(world);
    if (options.policy) aiPolicySystem(world);
    trace.push(snapshot(world, player, ids));
    for (const id of ids) {
      const move = world.get(id, MoveIntent);
      if (!move) continue;
      const p = world.get(id, Position);
      p.x += move.dx;
      p.y += move.dy;
      world.remove(id, MoveIntent);
    }
    world.step += 1;
    rebuildSpatialIndex(world);
  }
  clearAll();
  console.log(JSON.stringify({ name, trace }));
}

run("chase-only", { policy: false });
run("chase-plus-policy", { policy: true });
run("standing-still", { policy: false, playerStrategy: "still" });
run("retreat-through-corridor", { policy: false, corridor: true, playerStrategy: "retreat" });
run("disabled-first-target", { policy: false, stunned: true });
run("ranged-group", { policy: false, archer: true });

